package com.bank.dept;

import java.util.*;
import java.util.logging.*;

public class DeptDirectoryDemo {
    private static final Logger log = Logger.getLogger("DeptDir");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee(1L, "Rajesh", "IT"),
            new Employee(2L, "Priya", "Finance"),
            new Employee(3L, "Amit", "IT"),
            new Employee(4L, "Sneha", "Finance"),
            new Employee(5L, "Vikram", "HR")
        );
        DirectoryService service = new DirectoryService();
        Map<String, List<Employee>> byDept = service.byDepartment(staff);
        byDept.forEach((dept, list) -> log.info(() ->
            dept + " -> " + list.stream().map(Employee::getName).toList()));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
    private final String department;
    Employee(Long id, String name, String department) { this.id = id; this.name = name; this.department = department; }
    String getName() { return name; }
    String getDepartment() { return department; }
}

// ─── Would be in service/DirectoryService.java ───
class DirectoryService {
    // groupingBy: one List per department. TreeMap::new keys departments alphabetically.
    Map<String, List<Employee>> byDepartment(List<Employee> employees) {
        return employees.stream()
            .collect(java.util.stream.Collectors.groupingBy(
                Employee::getDepartment, TreeMap::new, java.util.stream.Collectors.toList()));
    }
}
